from collections import defaultdict as d
def solve():
  n = int(input())
  mp = d(int)
  for i in range(n):
    mp[input()] += 1
  cnt = 0
  for i in range(n):
    string = input()
    if mp[string] != 0:
      mp[string] -= 1
    else:
      cnt += 1
      if string in "MSL":
        if mp["M"] > 0:
          mp["M"] -= 1
        elif mp["S"] > 1:
          mp["S"] -= 1
        else:
          mp["L"] -= 1
      elif string in "XSXL":
        if mp["XL"] > 0:
          mp["XL"] -= 1
        else:
          mp["XS"] -= 1
      elif string in "XXSXXL":
        if mp["XXL"] > 0:
          mp["XXL"] -= 1
        else:
          mp["XXS"] -= 1
      elif string in "XXXSXXXL":
        if mp["XXXL"] > 0:
          mp["XXXL"] -= 1
        else:
          mp["XXXS"] -= 1
  return cnt


t = 1
while t != 0:
  res = solve()
  print(res)
  t -= 1

