def solve(xs):
    counts = [collections.Counter(s) for s in xs if len(set(s)) <= 2]
    all_letters = set(it.chain.from_iterable(counts))
    maxval = 0
    for (a, b) in it.combinations(all_letters, 2):
        maxlocal = 0
        for d in counts:
            if all(l in (a, b) for l in d):
                maxlocal += d[a] + d[b]
        maxval = max(maxval, maxlocal)
    return maxval

