# -*- coding: utf-8 -*-



def solve(b, p1, p2) -> bool:
    '''
    b:  (int, int)
    p1: (int, int)
    p2: (int, int)
    '''
    large = max(b)
    small = min(b)
    min_p1 = min(p1)
    min_p2 = min(p2)
    max_p1 = max(p1)
    max_p2 = max(p2)
    if min_p1 + min_p2 <= small and max(max_p1, max_p2) <= large:
        return True
    elif max(max_p1, min_p2) <= small and min_p1 + max_p2 <= large:
        return True
    elif max(max_p2, min_p1) <= small and min_p2 + max_p1 <= large:
        return True
    else:
        return False


