def dfs(startnode, color):
  stack = []
  stack.append(startnode)
  startnode.visited = True
  startnode.cv = color
  while stack:
    actualnode = stack.pop()
    for neighbour in actualnode.adjacencyList:
      if not neighbour.visited:
        neighbour.visited = True
        neighbour.cv = color
        stack.append(neighbour)
