void dfs(int v, int pr = -1){
    bool isleaf = 1;
    for(auto to : g[v]){
        if(to != pr){
            isleaf = false;
            dfs(to, v);
        }
    }
    leaf[v] = isleaf;
}

void dfs1(int v, int pr = -1){
    int cur = 0;
    if(leaf[v]){
        return;
    }
    for(auto to : g[v]){
        if(to != pr){
            cur += leaf[to];
        }
    }
    if(cur < 3){
        cout << "No";
        exit(0);
    }
}
