bool quality(string& s1, string& s2)
{
 if (s1.size() != s2.size()) return 0;
 for (int i = 0; i < s1.size(); ++i)
 {
  if (s1[i] == s2[i]) continue;
  if (toupper(s1[i]) == toupper(s2[i])) continue;
  if (s1[i] == '0' && toupper(s2[i]) == 'O')
  {
   continue;
  }
  if (s1[i] == '1' && (toupper(s2[i]) == 'L' || toupper(s2[i]) == 'I')) continue;
  swap(s1[i], s2[i]);
  if (s1[i] == '0' && toupper(s2[i]) == 'O')
  {
   swap(s1[i], s2[i]);
   continue;
  }
  if (s1[i] == '1' && (toupper(s2[i]) == 'L' || toupper(s2[i]) == 'I'))
  {
   swap(s1[i], s2[i]);
   continue;
  }
  swap(s1[i], s2[i]);
  return 0;
 }
 return 1;
}
